import os

SKIP_DIRS = {'.git', '__pycache__', '.codex'}
TEXT_EXTS = {'.csv', '.json', '.txt', '.md', '.py', '.tsv', '.log', '.yml', '.yaml', '.xml', '.html'}
MAX_PRINT = 250_000


def main():
    for root, dirs, files in os.walk('.'):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        rel = os.path.relpath(root, '.')
        label = '.' if rel == '.' else rel
        print('=' * 70)
        print(f'DIR: {label}/')
        print('=' * 70)
        for f in sorted(files):
            fpath = os.path.join(root, f)
            size = os.path.getsize(fpath)
            ext = os.path.splitext(f)[1].lower()
            print(f'--- FILE: {fpath} ({size} bytes) ---')
            if ext not in TEXT_EXTS:
                print('[skipped: not plain text]')
                print()
                continue
            if size > MAX_PRINT:
                print(f'[too large, showing first {MAX_PRINT} bytes]')
            try:
                with open(fpath, 'r', encoding='utf-8', errors='replace') as fh:
                    data = fh.read(MAX_PRINT)
                print(data)
            except Exception as e:
                print(f'[error reading: {e}]')
            print()


if __name__ == '__main__':
    main()

